desafio_04_surpresa.pacote_kev_emitido:
KEV/1.0 domain=BRIDGE_3D target=IndustrialStationNodeActor
@SPACE{unit=METRIC;scale=1.0;up=Z;size_x=5.0;size_y=2.2;size_z=3.2;pivot_z_min=0.0;manifold=true;collider=UCX_Estacao_01}
@GRAPH[
  S1:BMESH.init_metric_scene(scale=1.0,empty=true) -> S2
  S2:BMESH.create_cube_and_inset(size_x=5.0,size_y=2.2,size_z=3.2,z_min=0.0,ribs=2) -> S3
  S3:BMESH.loops_uv_verify_grid(outward=true,mesh=Estacao_01) -> S4
  S4:BMESH.convex_hull_collider(name=UCX_Estacao_01,manifold=true) -> S5
  S5:UHT.header_order_last_include(gen_hlsl=true,last_inc=HeaderStem.generated.h) -> S6
  S6:UHT.delegates_and_struct(multicast=true,tick=false,scale_m=1.0,scale_cm=100.0)
]
@GUARD[
  !SCALE-1M-100CM: Multiplicar dimensoes em metros pelo 100 para validar AABB em centimetros no UE5 (ex: 5.0m -> 500.0cm, +-2%)
  !MANIFOLD-0EDGES: Garantir non_manifold_edges==0 e zero_area_faces==0 na malha principal Estacao_01 do Blender
  !PIVOT-ORIGIN-Z0: Colisor UCX_Estacao_01 origin em (0,0,0) e base apoiada em Z_min=0.0 dentro de +-2% da AABB
]
@VERIFY[
  ?non_manifold_edges==0
  ?zero_area_faces==0
  ?unit_scale_meters==1.0
  ?meter_to_cm==100.0
  ?bbox_tol_pct<=2.0
]
